package com.tripmateai.entity;
import com.tripmateai.enums.NotificationType; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications",indexes={@Index(name="idx_notifications_user_read",columnList="user_id,is_read"),@Index(name="idx_notifications_type",columnList="notification_type")}) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class Notification extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @Enumerated(EnumType.STRING) @Column(name="notification_type",nullable=false,length=40) private NotificationType notificationType; @NotBlank @Size(max=200) @Column(nullable=false,length=200) private String title; @NotBlank @Size(max=5000) @Column(nullable=false,columnDefinition="TEXT") private String message; @Column(name="is_read",nullable=false) private boolean read; @Column(name="read_at") private LocalDateTime readAt; }
